<script setup lang="ts">
import { Head, Link, router, useForm, usePage } from '@inertiajs/vue3';
import { computed, ref, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import Breadcrumbs from '../../../components/admin/Breadcrumbs.vue';
import PageHeader from '../../../components/admin/PageHeader.vue';
import StatusBadge from '../../../components/admin/StatusBadge.vue';
import FieldError from '../../../components/FieldError.vue';
import AdminLayout from '../../../layouts/AdminLayout.vue';
import type { PageProps } from '../../../types';

interface Address { recipient_name: string | null; phone: string | null; country_code: string | null; region: string | null; city: string | null; district: string | null; address_line_1: string | null; address_line_2: string | null; postal_code: string | null; reference: string | null }
interface Reservation { id: string; location: string; code: string; quantity: number; status: string }
interface Item { id: string; product_name: string; variant_name: string | null; sku: string; quantity: number; base_unit_price: string; discount_unit_amount: string; final_unit_price: string; line_base_total: string; line_discount_total: string; line_total: string; promotion_name: string | null; tax_category_code: string | null; tax_rate: string | null; taxable_amount: string | null; exempt_amount: string | null; unaffected_amount: string | null; tax_amount: string | null; reservations: Reservation[] }
interface History { id: string; from_status: string | null; to_status: string; reason: string | null; actor: string | null; created_at: string }
interface Order { id: string; order_number: string; checkout_session_id: string; cart_id: string | null; status: string; payment_status: string; fulfillment_status: string; currency: string; customer_name: string | null; email: string | null; phone: string | null; shipping: Address; billing: Address; delivery_type: string; subtotal_before_discounts: string; discount_total: string; subtotal: string; shipping_total: string; tax_total: string; taxable_amount: string | null; exempt_amount: string | null; unaffected_amount: string | null; tax_calculated_at: string | null; grand_total: string; placed_at: string; cancelled_at: string | null; created_at: string | null; items: Item[]; history: History[] }
interface PaymentTransaction { id: string; type: string; status: string; amount: string; occurred_at: string }
interface Payment { id: string; method: string; provider: string; status: string; amount: string; currency: string; captured_amount: string; external_reference: string | null; can_capture: boolean; can_cancel: boolean; transactions: PaymentTransaction[] }
interface PaymentData { balance: { order_total: string; captured_total: string; remaining_total: string; payment_status: string }; plan: { terms: string; total_amount: string; amount_due_now: string; amount_due_later: string; deposit_type: string | null; deposit_value: string | null; persisted: boolean }; enabled_methods: Record<'BANK_TRANSFER' | 'CASH', boolean>; can_manage: boolean; can_capture: boolean; payments: Payment[] }
interface FulfillmentSummary { id: string; status: string; location_name: string; location_code: string; item_count: number; total_quantity: number; shipment_status?: string | null; created_at: string | null }
interface AvailableReservation { inventory_reservation_id: string; order_item_id: string; product_name: string; variant_name: string | null; sku: string; remaining_quantity: number }
interface AvailableLocation { id: string; name: string; code: string; items: AvailableReservation[] }
interface FulfillmentData { summary: { ordered_quantity: number; fulfilled_quantity: number; remaining_quantity: number; status: string }; fulfillments: FulfillmentSummary[]; available_locations: AvailableLocation[]; payment_eligibility: { eligible: boolean; reason: string | null }; can_manage: boolean; can_complete: boolean; can_manage_shipments: boolean }
interface FiscalData { can_issue: boolean; documents: { id: string; full_number: string; document_type: string; status: string; grand_total: string }[] }
interface ProfitabilityItem { order_item_id: string; product_name: string; variant_name: string | null; sku: string; ordered_quantity: number; fulfilled_quantity: number; covered_quantity: number; ordered_revenue_ex_tax: string; fulfilled_revenue_ex_tax: string; cogs: string; gross_profit: string | null; gross_margin_percent: string | null; complete: boolean }
interface Profitability { currency: string; ordered_revenue_ex_tax: string; fulfilled_revenue_ex_tax: string; cogs: string; gross_profit: string | null; gross_margin_percent: string | null; fulfilled_quantity: number; covered_quantity: number; cost_coverage_percent: string; status: string; items: ProfitabilityItem[] }
interface RelatedCustomer { id: string; display_name: string; email: string | null; phone: string | null }
interface RelatedReturn { id: string; short_id: string; status: string; requested_at: string | null; item_count: number }
interface RelatedLinks { customer: string | null; payments: string | null; refunds: string | null; returns: string | null; fulfillments: string | null }

const props = defineProps<{ order: Order; customer: RelatedCustomer | null; returns: RelatedReturn[] | null; relatedLinks: RelatedLinks; canCancel: boolean; paymentData: PaymentData | null; fulfillmentData: FulfillmentData | null; fiscalData: FiscalData | null; profitability: Profitability | null }>();
const page = usePage<PageProps>();
const { t, te, locale } = useI18n();
const flashStatus = computed(() => page.props.status);
const serverErrors = computed(() => page.props.errors as Record<string, string | undefined>);
const cancelForm = useForm({ reason: '' });
const initialMethod = props.paymentData?.enabled_methods.BANK_TRANSFER ? 'BANK_TRANSFER' : (props.paymentData?.enabled_methods.CASH ? 'CASH' : '');
const paymentForm = useForm({ method: initialMethod, amount: props.paymentData?.balance.remaining_total ?? '', external_reference: '', idempotency_key: crypto.randomUUID() });
const termsForm = useForm({ terms: props.paymentData?.plan.terms ?? 'PREPAID' });
const fulfillmentForm = useForm<{ inventory_location_id: string; items: { inventory_reservation_id: string; quantity: number }[] }>({ inventory_location_id: '', items: [] });
const canManageReturns = computed(() => page.props.currentTenantMembership?.permissions.includes('returns.manage') ?? false);
const returnForm = useForm<{ reason: string; notes: string; items: { order_item_id: string; quantity: number; reason: string }[] }>({ reason: '', notes: '', items: props.order.items.map((item) => ({ order_item_id: item.id, quantity: 0, reason: '' })) });
const fiscalForm = useForm({ document_type: 'RECEIPT', customer_document_type: '', customer_document_number: '', customer_name: props.order.customer_name ?? '', customer_address: '' });
const fulfillmentQuantities = ref<Record<string, number>>({});
const returnItemError = computed(() => Object.entries(returnForm.errors as Record<string, string | undefined>).find(([key]) => key.startsWith('items.'))?.[1]);

const statusLabel = (value: string | null) => value && te(`status.${value}`) ? t(`status.${value}`) : (value ?? t('orders.createdStatus'));
const enumLabel = (group: string, value: string | null) => value && te(`orders.${group}.${value}`) ? t(`orders.${group}.${value}`) : (value ?? t('common.none'));
const formatDate = (value: string | null) => value ? new Intl.DateTimeFormat(locale.value, { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : t('orders.notDated');
const formatQuantity = (value: number) => new Intl.NumberFormat(locale.value).format(value);
const formatDecimal = (value: string) => { const [integer, decimal = ''] = value.split('.'); return `${BigInt(integer).toLocaleString(locale.value)}${decimal ? `${locale.value.startsWith('es') ? ',' : '.'}${decimal}` : ''}`; };
const money = (amount: string) => `${props.order.currency} ${formatDecimal(amount)}`;
const addressLines = (address: Address): string[] => [address.recipient_name, address.phone, address.address_line_1, address.address_line_2, [address.district, address.city, address.region].filter(Boolean).join(', '), [address.country_code, address.postal_code].filter(Boolean).join(' '), address.reference].filter((line): line is string => Boolean(line));
const addressTypes: ('shipping' | 'billing')[] = ['shipping', 'billing'];
const shortId = (value: string | null) => value ? value.slice(0, 8) : t('common.none');
const eligibilityReason = computed(() => { const reason = props.fulfillmentData?.payment_eligibility.reason; return reason && te(`orders.eligibility.${reason}`) ? t(`orders.eligibility.${reason}`) : null; });

const cancelOrder = () => { if (window.confirm(t('orders.cancelConfirm'))) cancelForm.post(`/admin/orders/${props.order.id}/cancel`, { preserveScroll: true }); };
const createPayment = () => paymentForm.post(`/admin/orders/${props.order.id}/payments`, { preserveScroll: true, onSuccess: () => { paymentForm.idempotency_key = crypto.randomUUID(); } });
const updateTerms = () => termsForm.patch(`/admin/orders/${props.order.id}/payment-terms`, { preserveScroll: true });
const captureKeys = new Map<string, string>();
const capture = (payment: Payment) => { const key = captureKeys.get(payment.id) ?? crypto.randomUUID(); captureKeys.set(payment.id, key); router.post(`/admin/payments/${payment.id}/capture`, { amount: payment.amount, idempotency_key: key }, { preserveScroll: true, onSuccess: () => captureKeys.delete(payment.id) }); };
const cancelPayment = (payment: Payment) => { if (window.confirm(t('orders.cancelPaymentConfirm'))) router.post(`/admin/payments/${payment.id}/cancel`, {}, { preserveScroll: true }); };
const createFulfillment = (location: AvailableLocation) => { fulfillmentForm.inventory_location_id = location.id; fulfillmentForm.items = location.items.map((item) => ({ inventory_reservation_id: item.inventory_reservation_id, quantity: Number(fulfillmentQuantities.value[item.inventory_reservation_id] ?? 0) })).filter((item) => item.quantity > 0); fulfillmentForm.post(`/admin/orders/${props.order.id}/fulfillments`, { preserveScroll: true, onSuccess: () => { fulfillmentQuantities.value = {}; } }); };
const createReturn = () => returnForm.transform((data) => ({ ...data, items: data.items.filter((item) => Number(item.quantity) > 0) })).post(`/admin/orders/${props.order.id}/returns`, { preserveScroll: true, onSuccess: () => returnForm.reset() });
const issueFiscalDocument = () => fiscalForm.post(`/admin/orders/${props.order.id}/fiscal-document`, { preserveScroll: true });
watch(() => props.paymentData?.balance.remaining_total, (remaining) => { if (remaining) paymentForm.amount = remaining; });
</script>

<template>
    <Head :title="t('orders.detailTitle', { number: order.order_number })" />
    <AdminLayout>
        <section class="mx-auto grid w-full max-w-[90rem] gap-5 sm:gap-6">
            <Breadcrumbs :items="[{ label: t('nav.sales') }, { label: t('orders.title'), href: '/admin/orders' }, { label: order.order_number }]" />
            <PageHeader :title="order.order_number" :eyebrow="t('orders.commercialRecord')" :description="t('orders.placedOn', { date: formatDate(order.placed_at) })"><template #actions><Link href="/admin/orders" class="inline-flex min-h-9 w-full items-center justify-center rounded-md border border-admin-border-strong bg-white px-4 text-sm font-semibold sm:w-auto">{{ t('orders.back') }}</Link></template></PageHeader>
            <p v-if="flashStatus" class="rounded-md border border-admin-success-border bg-admin-success-bg p-3 text-sm font-medium text-admin-success" role="status">{{ flashStatus }}</p>

            <div class="grid gap-3 sm:grid-cols-3"><article v-for="entry in [{ label: t('orders.orderStatus'), value: order.status }, { label: t('orders.paymentStatus'), value: order.payment_status }, { label: t('orders.fulfillmentStatus'), value: order.fulfillment_status }]" :key="entry.label" class="admin-card flex items-center justify-between gap-3 p-3"><p class="admin-label">{{ entry.label }}</p><StatusBadge :status="entry.value" /></article></div>

            <section class="grid gap-4 lg:grid-cols-[minmax(0,2fr)_minmax(18rem,1fr)]">
                <article class="admin-card p-4 sm:p-5"><div><p class="admin-label text-admin-secondary">{{ t('orders.generalSection') }}</p><h2 class="mt-1 text-lg font-semibold">{{ t('orders.general') }}</h2></div><dl class="mt-4 grid gap-x-6 gap-y-4 sm:grid-cols-2"><div><dt class="admin-label">{{ t('orders.customerSnapshot') }}</dt><dd class="mt-1 text-sm font-medium">{{ order.customer_name ?? t('orders.guest') }}</dd></div><div><dt class="admin-label">{{ t('orders.deliveryType') }}</dt><dd class="mt-1 text-sm">{{ enumLabel('delivery', order.delivery_type) }}</dd></div><div><dt class="admin-label">{{ t('orders.email') }}</dt><dd class="mt-1 break-words text-sm">{{ order.email ?? t('orders.noEmail') }}</dd></div><div><dt class="admin-label">{{ t('orders.phone') }}</dt><dd class="mt-1 text-sm">{{ order.phone ?? t('orders.noPhone') }}</dd></div><div><dt class="admin-label">{{ t('orders.checkoutSnapshot') }}</dt><dd class="mt-1 font-mono text-xs">{{ shortId(order.checkout_session_id) }}</dd></div><div><dt class="admin-label">{{ t('orders.sourceCart') }}</dt><dd class="mt-1 font-mono text-xs">{{ shortId(order.cart_id) }}</dd></div><div><dt class="admin-label">{{ t('orders.createdAt') }}</dt><dd class="mt-1 text-sm">{{ formatDate(order.created_at) }}</dd></div><div v-if="order.cancelled_at"><dt class="admin-label">{{ t('orders.cancelledAt') }}</dt><dd class="mt-1 text-sm text-admin-danger">{{ formatDate(order.cancelled_at) }}</dd></div></dl></article>
                <article class="admin-card p-4 sm:p-5"><p class="admin-label text-admin-secondary">{{ t('orders.customerSection') }}</p><h2 class="mt-1 text-lg font-semibold">{{ t('orders.authorizedCustomer') }}</h2><template v-if="customer"><p class="mt-4 font-medium">{{ customer.display_name }}</p><p class="mt-1 break-words text-sm text-admin-neutral">{{ customer.email ?? t('orders.noEmail') }}</p><p class="mt-1 text-sm text-admin-neutral">{{ customer.phone ?? t('orders.noPhone') }}</p><Link v-if="relatedLinks.customer" :href="relatedLinks.customer" class="admin-link mt-4 inline-block text-sm">{{ t('orders.openCustomer') }}</Link></template><p v-else class="mt-4 text-sm text-admin-neutral">{{ t('orders.noLinkedCustomer') }}</p></article>
            </section>

            <section class="grid gap-4 lg:grid-cols-2"><article v-for="type in addressTypes" :key="type" class="admin-card p-4 sm:p-5"><p class="admin-label text-admin-secondary">{{ t(`orders.address.${type}Section`) }}</p><h2 class="mt-1 text-lg font-semibold">{{ t(`orders.address.${type}`) }}</h2><p v-if="!addressLines(order[type]).length" class="mt-4 text-sm text-admin-neutral">{{ t('orders.notProvided') }}</p><div v-else class="mt-4 text-sm leading-6"><p v-for="line in addressLines(order[type])" :key="line">{{ line }}</p></div></article></section>

            <nav v-if="relatedLinks.payments || relatedLinks.refunds || relatedLinks.returns || relatedLinks.fulfillments" class="admin-card flex flex-wrap gap-2 p-3" :aria-label="t('orders.relatedResources')"><Link v-if="relatedLinks.payments" :href="relatedLinks.payments" class="rounded-md border border-admin-border-strong px-3 py-2 text-xs font-semibold">{{ t('orders.allPayments') }}</Link><Link v-if="relatedLinks.refunds" :href="relatedLinks.refunds" class="rounded-md border border-admin-border-strong px-3 py-2 text-xs font-semibold">{{ t('orders.refunds') }}</Link><Link v-if="relatedLinks.returns" :href="relatedLinks.returns" class="rounded-md border border-admin-border-strong px-3 py-2 text-xs font-semibold">{{ t('orders.returns') }}</Link><Link v-if="relatedLinks.fulfillments" :href="relatedLinks.fulfillments" class="rounded-md border border-admin-border-strong px-3 py-2 text-xs font-semibold">{{ t('orders.fulfillments') }}</Link></nav>

            <section><div class="mb-3"><p class="admin-label text-admin-secondary">{{ t('orders.linesSection') }}</p><h2 class="mt-1 text-xl font-semibold">{{ t('orders.orderLines') }}</h2><p class="mt-1 text-sm text-admin-neutral">{{ t('orders.linesHelp') }}</p></div><div class="grid gap-3"><article v-for="item in order.items" :key="item.id" class="admin-card p-4"><div class="flex flex-col gap-4 xl:flex-row xl:justify-between"><div class="min-w-0"><h3 class="font-semibold">{{ item.product_name }}</h3><p class="mt-1 break-words text-xs text-admin-neutral">{{ item.variant_name ?? t('orders.defaultVariant') }} · {{ item.sku }} · {{ t('orders.quantityValue', { count: formatQuantity(item.quantity) }) }}</p><p v-if="item.promotion_name" class="mt-2 text-xs font-semibold text-admin-secondary">{{ item.promotion_name }}</p><p v-if="item.tax_category_code" class="mt-2 font-mono text-xs text-admin-neutral">{{ item.tax_category_code }} · {{ formatDecimal(item.tax_rate ?? '0.0000') }}% · {{ t('orders.taxAmount', { amount: money(item.tax_amount ?? '0.0000') }) }}</p></div><dl class="grid grid-cols-2 gap-x-5 gap-y-3 text-xs sm:grid-cols-3 xl:min-w-[34rem]"><div><dt class="admin-label">{{ t('orders.baseUnit') }}</dt><dd class="mt-1 font-mono">{{ money(item.base_unit_price) }}</dd></div><div><dt class="admin-label">{{ t('orders.unitDiscount') }}</dt><dd class="mt-1 font-mono">{{ money(item.discount_unit_amount) }}</dd></div><div><dt class="admin-label">{{ t('orders.finalUnit') }}</dt><dd class="mt-1 font-mono">{{ money(item.final_unit_price) }}</dd></div><div><dt class="admin-label">{{ t('orders.lineBase') }}</dt><dd class="mt-1 font-mono">{{ money(item.line_base_total) }}</dd></div><div><dt class="admin-label">{{ t('orders.lineDiscount') }}</dt><dd class="mt-1 font-mono">{{ money(item.line_discount_total) }}</dd></div><div><dt class="admin-label">{{ t('orders.lineTotal') }}</dt><dd class="mt-1 font-mono font-semibold">{{ money(item.line_total) }}</dd></div></dl></div><dl v-if="item.tax_category_code" class="mt-4 grid grid-cols-2 gap-3 border-t border-admin-border pt-3 text-xs sm:grid-cols-4"><div><dt class="admin-label">{{ t('orders.taxable') }}</dt><dd class="mt-1 font-mono">{{ money(item.taxable_amount ?? '0.0000') }}</dd></div><div><dt class="admin-label">{{ t('orders.exempt') }}</dt><dd class="mt-1 font-mono">{{ money(item.exempt_amount ?? '0.0000') }}</dd></div><div><dt class="admin-label">{{ t('orders.unaffected') }}</dt><dd class="mt-1 font-mono">{{ money(item.unaffected_amount ?? '0.0000') }}</dd></div><div><dt class="admin-label">{{ t('orders.taxIncluded') }}</dt><dd class="mt-1 font-mono">{{ money(item.tax_amount ?? '0.0000') }}</dd></div></dl><div v-if="item.reservations.length" class="mt-4 flex flex-wrap gap-2"><span v-for="reservation in item.reservations" :key="reservation.id" class="rounded border border-admin-border bg-admin-canvas px-2 py-1 text-[11px]">{{ reservation.code }} · {{ formatQuantity(reservation.quantity) }} · {{ statusLabel(reservation.status) }}</span></div></article></div></section>

            <section class="grid gap-4 lg:grid-cols-2"><article class="admin-card p-4 sm:p-5"><p class="admin-label text-admin-secondary">{{ t('orders.totalsSection') }}</p><h2 class="mt-1 text-lg font-semibold">{{ t('orders.definitiveTotals') }}</h2><p v-if="order.tax_calculated_at" class="mt-1 text-xs text-admin-neutral">{{ t('orders.taxCalculated', { date: formatDate(order.tax_calculated_at) }) }}</p><dl class="mt-4 grid gap-2 text-sm"><div v-for="row in [{ label: t('orders.beforeDiscounts'), value: order.subtotal_before_discounts }, { label: t('orders.discount'), value: order.discount_total }, { label: t('orders.taxable'), value: order.taxable_amount ?? '0.0000' }, { label: t('orders.exempt'), value: order.exempt_amount ?? '0.0000' }, { label: t('orders.unaffected'), value: order.unaffected_amount ?? '0.0000' }, { label: t('orders.subtotal'), value: order.subtotal }, { label: t('orders.shipping'), value: order.shipping_total }, { label: t('orders.taxIncluded'), value: order.tax_total }]" :key="row.label" class="flex justify-between gap-4 border-b border-admin-border pb-2"><dt class="text-admin-text-secondary">{{ row.label }}</dt><dd class="font-mono tabular-nums">{{ money(row.value) }}</dd></div><div class="flex justify-between gap-4 pt-1 text-base font-semibold"><dt>{{ t('orders.grandTotal') }}</dt><dd class="font-mono tabular-nums">{{ money(order.grand_total) }}</dd></div></dl></article><article class="admin-card p-4 sm:p-5"><p class="admin-label text-admin-secondary">{{ t('orders.historySection') }}</p><h2 class="mt-1 text-lg font-semibold">{{ t('orders.statusHistory') }}</h2><ol class="mt-4 grid gap-4"><li v-for="entry in order.history" :key="entry.id" class="border-l-2 border-admin-secondary pl-3"><p class="text-sm font-semibold">{{ statusLabel(entry.from_status) }} → {{ statusLabel(entry.to_status) }}</p><p class="mt-1 text-xs text-admin-neutral">{{ formatDate(entry.created_at) }} · {{ entry.actor ?? t('orders.systemActor') }}</p><p v-if="entry.reason" class="mt-1 text-sm">{{ entry.reason }}</p></li></ol></article></section>

            <section v-if="paymentData" class="rounded-lg bg-admin-primary p-4 text-white sm:p-5"><div class="flex flex-col gap-4 border-b border-white/15 pb-4 sm:flex-row sm:items-end sm:justify-between"><div><p class="admin-label text-sky-300">{{ t('orders.financialSection') }}</p><h2 class="mt-1 text-xl font-semibold">{{ t('orders.payments') }}</h2></div><dl class="grid grid-cols-3 gap-4 text-right text-xs"><div><dt class="text-white/60">{{ t('orders.total') }}</dt><dd class="mt-1 font-mono">{{ money(paymentData.balance.order_total) }}</dd></div><div><dt class="text-white/60">{{ t('orders.captured') }}</dt><dd class="mt-1 font-mono text-sky-300">{{ money(paymentData.balance.captured_total) }}</dd></div><div><dt class="text-white/60">{{ t('orders.remaining') }}</dt><dd class="mt-1 font-mono">{{ money(paymentData.balance.remaining_total) }}</dd></div></dl></div><div class="mt-4 grid gap-4 lg:grid-cols-[minmax(16rem,1fr)_2fr]"><article class="rounded-md border border-white/20 p-4"><p class="admin-label text-white/60">{{ t('orders.termsSnapshot') }}</p><p class="mt-2 font-semibold">{{ enumLabel('terms', paymentData.plan.terms) }}</p><p class="mt-2 text-xs text-white/70">{{ t('orders.dueSummary', { now: money(paymentData.plan.amount_due_now), later: money(paymentData.plan.amount_due_later) }) }}</p><form v-if="paymentData.can_manage && paymentData.balance.captured_total === '0.0000'" class="mt-4 flex gap-2" @submit.prevent="updateTerms"><select v-model="termsForm.terms" class="admin-control min-w-0 flex-1 px-3 text-admin-primary"><option value="PREPAID">{{ enumLabel('terms', 'PREPAID') }}</option><option value="COD">{{ enumLabel('terms', 'COD') }}</option></select><button :disabled="termsForm.processing" class="rounded-md border border-sky-300 px-3 text-xs font-semibold text-sky-300 disabled:opacity-50">{{ t('common.applyRange') }}</button></form><FieldError :message="termsForm.errors.terms ?? serverErrors.payment_terms" /></article><form v-if="paymentData.can_manage" class="grid gap-3 rounded-md border border-white/20 p-4 sm:grid-cols-3" @submit.prevent="createPayment"><label class="grid gap-1 text-xs">{{ t('orders.method') }}<select v-model="paymentForm.method" class="admin-control px-3 text-admin-primary"><option v-if="paymentData.enabled_methods.BANK_TRANSFER" value="BANK_TRANSFER">{{ enumLabel('methods', 'BANK_TRANSFER') }}</option><option v-if="paymentData.enabled_methods.CASH" value="CASH">{{ enumLabel('methods', 'CASH') }}</option></select></label><label class="grid gap-1 text-xs">{{ t('orders.amount') }}<input v-model="paymentForm.amount" required inputmode="decimal" class="admin-control px-3 text-admin-primary" /></label><label class="grid gap-1 text-xs">{{ t('orders.referenceOptional') }}<input v-model="paymentForm.external_reference" maxlength="255" class="admin-control px-3 text-admin-primary" /></label><div class="sm:col-span-3"><FieldError :message="paymentForm.errors.method ?? paymentForm.errors.amount ?? paymentForm.errors.idempotency_key ?? serverErrors.payment" /><button :disabled="paymentForm.processing || !paymentForm.method || paymentData.balance.remaining_total === '0.0000'" class="rounded-md border border-sky-300 px-4 py-2 text-xs font-semibold text-sky-300 disabled:opacity-40">{{ t('orders.createPendingPayment') }}</button></div></form></div><div class="mt-4 grid gap-3"><article v-for="payment in paymentData.payments" :key="payment.id" class="rounded-md border border-white/20 p-4"><div class="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div class="min-w-0"><Link :href="`/admin/payments/${payment.id}`" class="break-all font-mono text-xs text-sky-300">{{ payment.id }}</Link><p class="mt-1 text-sm font-semibold">{{ enumLabel('methods', payment.method) }} · {{ enumLabel('providers', payment.provider) }} · {{ statusLabel(payment.status) }}</p><p class="mt-1 text-xs text-white/65">{{ money(payment.amount) }} · {{ t('orders.capturedValue', { amount: money(payment.captured_amount) }) }}<template v-if="payment.external_reference"> · {{ payment.external_reference }}</template></p></div><div class="flex flex-wrap gap-2"><button v-if="payment.can_capture" type="button" class="rounded border border-sky-300 px-3 py-2 text-xs text-sky-300" @click="capture(payment)">{{ t('orders.confirmPayment') }}</button><button v-if="payment.can_cancel" type="button" class="rounded border border-red-300 px-3 py-2 text-xs text-red-200" @click="cancelPayment(payment)">{{ t('common.cancel') }}</button></div></div><ul v-if="payment.transactions.length" class="mt-3 grid gap-1 border-t border-white/15 pt-3 text-xs text-white/60"><li v-for="transaction in payment.transactions" :key="transaction.id">{{ enumLabel('transactionTypes', transaction.type) }} · {{ statusLabel(transaction.status) }} · {{ money(transaction.amount) }} · {{ formatDate(transaction.occurred_at) }}</li></ul></article><p v-if="!paymentData.payments.length" class="text-sm text-white/60">{{ t('orders.noPayments') }}</p></div></section>

            <section v-if="fulfillmentData" class="admin-card p-4 sm:p-5"><div class="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><p class="admin-label text-admin-secondary">{{ t('orders.fulfillmentSection') }}</p><h2 class="mt-1 text-xl font-semibold">{{ t('orders.fulfillments') }}</h2></div><div class="rounded-md border px-3 py-2 text-xs" :class="fulfillmentData.payment_eligibility.eligible ? 'border-admin-success-border bg-admin-success-bg text-admin-success' : 'border-admin-warning-border bg-admin-warning-bg text-amber-800'"><strong>{{ fulfillmentData.payment_eligibility.eligible ? t('orders.paymentEligible') : t('orders.paymentBlocked') }}</strong><p v-if="eligibilityReason" class="mt-1">{{ eligibilityReason }}</p></div></div><dl class="mt-4 grid grid-cols-2 gap-px overflow-hidden rounded-md bg-admin-border sm:grid-cols-4"><div v-for="row in [{ label: t('orders.ordered'), value: formatQuantity(fulfillmentData.summary.ordered_quantity) }, { label: t('orders.fulfilled'), value: formatQuantity(fulfillmentData.summary.fulfilled_quantity) }, { label: t('orders.remaining'), value: formatQuantity(fulfillmentData.summary.remaining_quantity) }]" :key="row.label" class="bg-admin-canvas p-3"><dt class="admin-label">{{ row.label }}</dt><dd class="mt-1 font-mono font-semibold">{{ row.value }}</dd></div><div class="bg-admin-canvas p-3"><dt class="admin-label">{{ t('common.status') }}</dt><dd class="mt-1"><StatusBadge :status="fulfillmentData.summary.status" /></dd></div></dl><div class="mt-4 grid gap-3 sm:grid-cols-2"><Link v-for="fulfillment in fulfillmentData.fulfillments" :key="fulfillment.id" :href="`/admin/fulfillments/${fulfillment.id}`" class="rounded-md border border-admin-border p-3"><div class="flex items-start justify-between gap-3"><div><p class="text-sm font-semibold">{{ fulfillment.location_code }} · {{ fulfillment.location_name }}</p><p class="mt-1 text-xs text-admin-neutral">{{ t('orders.fulfillmentUnits', { lines: formatQuantity(fulfillment.item_count), units: formatQuantity(fulfillment.total_quantity) }) }}</p><p v-if="fulfillment.shipment_status" class="mt-1 text-xs text-admin-neutral">{{ t('orders.shipmentStatus', { status: statusLabel(fulfillment.shipment_status) }) }}</p></div><StatusBadge :status="fulfillment.status" /></div></Link><p v-if="!fulfillmentData.fulfillments.length" class="text-sm text-admin-neutral">{{ t('orders.noFulfillments') }}</p></div><div v-if="fulfillmentData.can_manage && fulfillmentData.available_locations.length" class="mt-6 border-t border-admin-border pt-5"><h3 class="font-semibold">{{ t('orders.createFromReservations') }}</h3><p class="mt-1 text-sm text-admin-neutral">{{ t('orders.fulfillmentHelp') }}</p><div class="mt-4 grid gap-4 lg:grid-cols-2"><form v-for="location in fulfillmentData.available_locations" :key="location.id" class="rounded-md border border-admin-border p-4" @submit.prevent="createFulfillment(location)"><div class="flex justify-between gap-3"><p class="font-semibold">{{ location.name }}</p><span class="font-mono text-xs text-admin-neutral">{{ location.code }}</span></div><div class="mt-4 grid gap-3"><label v-for="item in location.items" :key="item.inventory_reservation_id" class="grid grid-cols-[minmax(0,1fr)_5rem] items-center gap-3 text-sm"><span class="min-w-0"><strong class="block truncate">{{ item.product_name }}</strong><span class="text-xs text-admin-neutral">{{ item.variant_name ?? t('orders.defaultVariant') }} · {{ item.sku }} · {{ t('orders.remainingValue', { count: formatQuantity(item.remaining_quantity) }) }}</span></span><input v-model.number="fulfillmentQuantities[item.inventory_reservation_id]" type="number" min="0" :max="item.remaining_quantity" :aria-label="t('orders.fulfillQuantityFor', { product: item.product_name })" class="admin-control w-full px-2 font-mono" /></label></div><FieldError :message="fulfillmentForm.errors.items ?? fulfillmentForm.errors.inventory_location_id ?? serverErrors.quantity ?? serverErrors.reservation ?? serverErrors.payment" /><button :disabled="fulfillmentForm.processing || !fulfillmentData.payment_eligibility.eligible" class="mt-4 rounded-md bg-admin-primary px-4 py-2 text-xs font-semibold text-white disabled:opacity-40">{{ t('orders.createFulfillment') }}</button></form></div></div></section>

            <section v-if="returns !== null" class="admin-card p-4 sm:p-5"><p class="admin-label text-admin-secondary">{{ t('orders.returnsSection') }}</p><h2 class="mt-1 text-xl font-semibold">{{ t('orders.returns') }}</h2><div v-if="returns.length" class="mt-4 grid gap-3 sm:grid-cols-2"><Link v-for="entry in returns" :key="entry.id" :href="`/admin/returns/${entry.id}`" class="rounded-md border border-admin-border p-3"><div class="flex items-center justify-between gap-3"><p class="font-mono text-xs font-semibold text-admin-secondary">{{ entry.short_id }}</p><StatusBadge :status="entry.status" /></div><p class="mt-2 text-xs">{{ t('orders.returnLines', { count: formatQuantity(entry.item_count) }) }}</p><p class="mt-1 text-xs text-admin-neutral">{{ formatDate(entry.requested_at) }}</p></Link></div><p v-else class="mt-4 text-sm text-admin-neutral">{{ t('orders.noReturns') }}</p></section>

            <form v-if="canManageReturns && order.fulfillment_status !== 'UNFULFILLED'" class="admin-card p-4 sm:p-5" @submit.prevent="createReturn"><p class="admin-label text-admin-secondary">{{ t('orders.reverseSection') }}</p><h2 class="mt-1 text-xl font-semibold">{{ t('orders.createReturn') }}</h2><p class="mt-1 text-sm text-admin-neutral">{{ t('orders.returnHelp') }}</p><div class="mt-4 grid gap-3"><div v-for="(item, index) in order.items" :key="`return-${item.id}`" class="grid gap-3 rounded-md border border-admin-border bg-admin-canvas p-3 sm:grid-cols-[minmax(0,1fr)_7rem_minmax(0,1fr)]"><div class="min-w-0"><p class="truncate text-sm font-semibold">{{ item.product_name }}</p><p class="text-xs text-admin-neutral">{{ item.sku }} · {{ t('orders.orderedValue', { count: formatQuantity(item.quantity) }) }}</p></div><label class="grid gap-1 text-xs">{{ t('orders.quantity') }}<input v-model.number="returnForm.items[index].quantity" type="number" min="0" max="9999" class="admin-control px-2 font-mono" /></label><label class="grid gap-1 text-xs">{{ t('orders.itemReason') }}<input v-model="returnForm.items[index].reason" maxlength="500" class="admin-control px-3" /></label></div></div><div class="mt-4 grid gap-3 sm:grid-cols-2"><label class="grid gap-1 text-xs">{{ t('orders.overallReason') }}<input v-model="returnForm.reason" maxlength="500" class="admin-control px-3" /></label><label class="grid gap-1 text-xs">{{ t('orders.internalNotes') }}<textarea v-model="returnForm.notes" maxlength="5000" class="admin-control min-h-20 p-3" /></label></div><FieldError :message="returnForm.errors.items ?? returnItemError ?? returnForm.errors.reason ?? returnForm.errors.notes ?? serverErrors.quantity ?? serverErrors.order" /><button :disabled="returnForm.processing" class="mt-4 rounded-md bg-admin-primary px-4 py-2 text-sm font-semibold text-white disabled:opacity-40">{{ t('orders.createReturnRequest') }}</button></form>

            <section v-if="fiscalData" class="admin-card p-4 sm:p-5"><p class="admin-label text-admin-secondary">{{ t('orders.fiscalSection') }}</p><h2 class="mt-1 text-xl font-semibold">{{ t('orders.fiscalDocuments') }}</h2><div v-if="fiscalData.documents.length" class="mt-4 grid gap-3 sm:grid-cols-2"><Link v-for="document in fiscalData.documents" :key="document.id" :href="`/admin/fiscal-documents/${document.id}`" class="rounded-md border border-admin-border p-3"><p class="font-mono text-sm font-semibold text-admin-secondary">{{ document.full_number }}</p><p class="mt-1 text-xs text-admin-neutral">{{ enumLabel('documents', document.document_type) }} · {{ statusLabel(document.status) }} · {{ money(document.grand_total) }}</p></Link></div><p v-else class="mt-4 text-sm text-admin-neutral">{{ t('orders.noFiscalDocuments') }}</p><form v-if="fiscalData.can_issue" class="mt-5 grid gap-3 border-t border-admin-border pt-5 sm:grid-cols-2" @submit.prevent="issueFiscalDocument"><label class="grid gap-1 text-xs">{{ t('orders.documentType') }}<select v-model="fiscalForm.document_type" class="admin-control px-3"><option value="RECEIPT">{{ enumLabel('documents', 'RECEIPT') }}</option><option value="INVOICE">{{ enumLabel('documents', 'INVOICE') }}</option></select></label><label class="grid gap-1 text-xs">{{ t('orders.customerDocumentType') }}<input v-model="fiscalForm.customer_document_type" :required="fiscalForm.document_type === 'INVOICE'" class="admin-control px-3" /></label><label class="grid gap-1 text-xs">{{ t('orders.customerDocumentNumber') }}<input v-model="fiscalForm.customer_document_number" :required="fiscalForm.document_type === 'INVOICE'" maxlength="80" class="admin-control px-3" /></label><label class="grid gap-1 text-xs">{{ t('orders.legalName') }}<input v-model="fiscalForm.customer_name" :required="fiscalForm.document_type === 'INVOICE'" maxlength="200" class="admin-control px-3" /></label><label v-if="fiscalForm.document_type === 'INVOICE'" class="grid gap-1 text-xs sm:col-span-2">{{ t('orders.fiscalAddress') }}<input v-model="fiscalForm.customer_address" required maxlength="500" class="admin-control px-3" /></label><div class="sm:col-span-2"><FieldError :message="fiscalForm.errors.document_type ?? fiscalForm.errors.customer_document_type ?? fiscalForm.errors.customer_document_number ?? fiscalForm.errors.customer_name ?? fiscalForm.errors.customer_address ?? serverErrors.fiscal" /><button :disabled="fiscalForm.processing" class="rounded-md bg-admin-primary px-4 py-2 text-sm font-semibold text-white disabled:opacity-40">{{ t('orders.issueDocument') }}</button></div></form></section>

            <section v-if="profitability" class="admin-card p-4 sm:p-5"><p class="admin-label text-admin-secondary">{{ t('orders.costingSection') }}</p><h2 class="mt-1 text-xl font-semibold">{{ t('orders.profitability') }}</h2><dl class="mt-4 grid grid-cols-2 gap-3 lg:grid-cols-5"><div v-for="row in [{ label: t('orders.orderedRevenue'), value: money(profitability.ordered_revenue_ex_tax) }, { label: t('orders.fulfilledRevenue'), value: money(profitability.fulfilled_revenue_ex_tax) }, { label: t('orders.cogs'), value: money(profitability.cogs) }, { label: t('orders.grossProfit'), value: profitability.gross_profit === null ? t('orders.incomplete') : money(profitability.gross_profit) }, { label: t('orders.margin'), value: profitability.gross_margin_percent === null ? t('orders.incomplete') : `${formatDecimal(profitability.gross_margin_percent)}%` }]" :key="row.label" class="rounded-md border border-admin-border bg-admin-canvas p-3"><dt class="admin-label">{{ row.label }}</dt><dd class="mt-1 font-mono text-xs font-semibold">{{ row.value }}</dd></div></dl><p class="mt-4 text-xs" :class="profitability.status === 'COMPLETE' ? 'text-admin-success' : 'text-amber-800'">{{ t('orders.costCoverage', { percent: formatDecimal(profitability.cost_coverage_percent), covered: formatQuantity(profitability.covered_quantity), total: formatQuantity(profitability.fulfilled_quantity), status: statusLabel(profitability.status) }) }}</p><div class="mt-4 hidden md:block"><table class="admin-table w-full table-fixed text-left text-xs"><thead><tr><th class="w-[34%] p-3">{{ t('orders.item') }}</th><th class="p-3 text-right">{{ t('orders.fulfilled') }}</th><th class="p-3 text-right">{{ t('orders.revenue') }}</th><th class="p-3 text-right">{{ t('orders.cogs') }}</th><th class="p-3 text-right">{{ t('orders.grossProfit') }}</th><th class="p-3 text-right">{{ t('orders.margin') }}</th></tr></thead><tbody class="divide-y divide-admin-border"><tr v-for="item in profitability.items" :key="item.order_item_id"><td class="p-3"><p class="truncate font-semibold">{{ item.product_name }}</p><p class="font-mono text-admin-neutral">{{ item.sku }}</p></td><td class="p-3 text-right">{{ formatQuantity(item.fulfilled_quantity) }} / {{ formatQuantity(item.ordered_quantity) }}</td><td class="p-3 text-right font-mono">{{ money(item.fulfilled_revenue_ex_tax) }}</td><td class="p-3 text-right font-mono">{{ money(item.cogs) }}</td><td class="p-3 text-right font-mono">{{ item.gross_profit === null ? '—' : money(item.gross_profit) }}</td><td class="p-3 text-right font-mono">{{ item.gross_margin_percent === null ? '—' : `${formatDecimal(item.gross_margin_percent)}%` }}</td></tr></tbody></table></div><div class="mt-4 grid gap-2 md:hidden"><article v-for="item in profitability.items" :key="`profit-${item.order_item_id}`" class="rounded-md border border-admin-border p-3"><p class="truncate text-sm font-semibold">{{ item.product_name }}</p><p class="font-mono text-xs text-admin-neutral">{{ item.sku }}</p><dl class="mt-3 grid grid-cols-2 gap-2 text-xs"><div><dt class="admin-label">{{ t('orders.fulfilled') }}</dt><dd>{{ formatQuantity(item.fulfilled_quantity) }} / {{ formatQuantity(item.ordered_quantity) }}</dd></div><div><dt class="admin-label">{{ t('orders.revenue') }}</dt><dd class="font-mono">{{ money(item.fulfilled_revenue_ex_tax) }}</dd></div><div><dt class="admin-label">{{ t('orders.cogs') }}</dt><dd class="font-mono">{{ money(item.cogs) }}</dd></div><div><dt class="admin-label">{{ t('orders.grossProfit') }}</dt><dd class="font-mono">{{ item.gross_profit === null ? '—' : money(item.gross_profit) }}</dd></div></dl></article></div></section>

            <form v-if="canCancel" class="rounded-lg border border-admin-danger-border bg-admin-danger-bg p-4 sm:p-5" @submit.prevent="cancelOrder"><p class="admin-label text-admin-danger">{{ t('orders.dangerSection') }}</p><h2 class="mt-1 text-xl font-semibold text-admin-danger">{{ t('orders.cancelOrder') }}</h2><p class="mt-1 text-sm text-admin-danger">{{ t('orders.cancelHelp') }}</p><label class="mt-4 grid gap-1 text-xs font-semibold text-admin-danger">{{ t('orders.administrativeReason') }}<textarea v-model="cancelForm.reason" required maxlength="500" class="admin-control min-h-24 bg-white p-3 text-admin-primary" /></label><FieldError :message="cancelForm.errors.reason ?? serverErrors.order" /><button :disabled="cancelForm.processing" class="mt-4 rounded-md border border-admin-danger px-4 py-2 text-sm font-semibold text-admin-danger disabled:opacity-40">{{ t('orders.cancelOrder') }}</button></form>
